import sys
from collections import defaultdict
import heapq

def read_input():
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    test_cases = []
    for _ in range(t):
        n = int(input[index])
        S = int(input[index + 1])
        index += 2
        edges = []
        for _ in range(n - 1):
            v_i = int(input[index])
            u_i = int(input[index + 1])
            w_i = int(input[index + 2])
            c_i = int(input[index + 3])
            edges.append((v_i, u_i, w_i, c_i))
            index += 4
        test_cases.append((n, S, edges))
    return test_cases

def process_case(n, S, edges):
    graph = defaultdict(list)
    for v_i, u_i, w_i, c_i in edges:
        graph[v_i].append((u_i, w_i, c_i))
        graph[u_i].append((v_i, w_i, c_i))

    def dijkstra():
        pq = [(-S, 1, 0)]
        visited = set()
        while pq:
            neg_weight_sum, node, cost = heapq.heappop(pq)
            weight_sum = -neg_weight_sum
            if node in visited:
                continue
            visited.add(node)
            if len(graph[node]) == 1 and node != 1:
                return cost
            for neighbor, weight, edge_cost in graph[node]:
                if neighbor not in visited:
                    new_weight_sum = weight_sum + weight
                    if new_weight_sum <= S:
                        heapq.heappush(pq, (-new_weight_sum, neighbor, cost))
                    else:
                        needed_reduction = new_weight_sum - S
                        steps = 0
                        while needed_reduction > 0:
                            needed_reduction = (needed_reduction + 1) // 2
                            steps += 1
                        heapq.heappush(pq, (-S, neighbor, cost + steps * edge_cost))
        return float('inf')

    return dijkstra()

def main():
    test_cases = read_input()
    results = []
    for n, S, edges in test_cases:
        result = process_case(n, S, edges)
        results.append(result)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
